#include <konjugate/relationshipProvider.hpp>

#include <cstddef>
#include <cstring>
#include <memory>
#include <span>
#include <vector>

namespace {

// PID controller, parallel (independent) form
// Parallel (independent) form:  u = Kp*e + Ki*integral(e) + Kd*de/dt
// where the error is e = setpoint - measurement. The control output is limited to [outputMin, outputMax] when
// outputMax > outputMin, and the integral stops growing while the output is held at a limit it is already pushing
// against (conditional integration), so it does not wind up. The derivative is taken on the error and passed through a
// first-order filter of time constant filterTime (no filtering when that is zero or less). The integral of the error,
// not the integral term itself, is what is remembered, so changing a gain while a run is going does not make the
// output jump.
class PidParallel final : public konjugate::sdk::v1::NodeProvider {
public:
    konjugate::sdk::v1::NodeProviderDescription describe() const override {
        using konjugate::sdk::v1::ScalarPort;
        return {
            "konjugate.pidParallel",
            "PID controller, parallel (independent) form",
            {
                ScalarPort{"measurement", "measurement", ""},
                ScalarPort{"setpoint", "setpoint", ""},
                ScalarPort{"kp", "kp", ""},
                ScalarPort{"ki", "ki", ""},
                ScalarPort{"kd", "kd", ""},
                ScalarPort{"filterTime", "filterTime", ""},
                ScalarPort{"outputMin", "outputMin", ""},
                ScalarPort{"outputMax", "outputMax", ""}
            },
            {
                ScalarPort{"control", "control", ""},
                ScalarPort{"error", "error", ""}
            }
        };
    }

    void evaluate(const konjugate::sdk::v1::EvaluationContext& context,
                  konjugate::sdk::v1::NodeOutputCollector& outputs) override {
        const double measurement = context.inputs.at("measurement");
        const double setpoint = context.inputs.at("setpoint");
        const double kp = context.inputs.at("kp");
        const double ki = context.inputs.at("ki");
        const double kd = context.inputs.at("kd");
        const double filterTime = context.inputs.at("filterTime");
        const double outputMin = context.inputs.at("outputMin");
        const double outputMax = context.inputs.at("outputMax");
        const double stepSize = context.stepSize;

        const double error = setpoint - measurement;

        double derivative = 0;
        if (havePrevious_ && stepSize > 0) {
            const double raw = (error - previousError_) / stepSize;
            if (filterTime > 0) filteredDerivative_ += stepSize / (filterTime + stepSize) * (raw - filteredDerivative_);
            else filteredDerivative_ = raw;
            derivative = filteredDerivative_;
        }

        double integral = integral_ + (stepSize > 0 ? error * stepSize : 0);
        double control = kp * error + ki * integral + kd * derivative;

        if (outputMax > outputMin) {
            if (control > outputMax) {
                control = outputMax;
                if (error > 0) integral = integral_;
            } else if (control < outputMin) {
                control = outputMin;
                if (error < 0) integral = integral_;
            }
        }

        integral_ = integral;
        previousError_ = error;
        havePrevious_ = true;

        outputs.addGradient("control", control);
        outputs.addGradient("error", error);
    }

    // What the controller remembers, so a fork or a resumed run carries on exactly.
    std::vector<std::byte> checkpoint() const override {
        const double values[4] = {integral_, previousError_, filteredDerivative_, havePrevious_ ? 1.0 : 0.0};
        std::vector<std::byte> payload(sizeof values);
        std::memcpy(payload.data(), values, sizeof values);
        return payload;
    }

    void restore(std::span<const std::byte> payload) override {
        double values[4];
        if (payload.size() != sizeof values) return;
        std::memcpy(values, payload.data(), sizeof values);
        integral_ = values[0];
        previousError_ = values[1];
        filteredDerivative_ = values[2];
        havePrevious_ = values[3] != 0.0;
    }

private:
    double integral_ = 0;
    double previousError_ = 0;
    double filteredDerivative_ = 0;
    bool havePrevious_ = false;
};

}

std::unique_ptr<konjugate::sdk::v1::NodeProvider> createNodeProvider() {
    return std::make_unique<PidParallel>();
}
